from flask import Flask, jsonify

app = Flask(__name__)


@app.get("/posts/<int:post_id>")
def post_by_id(post_id):
    return jsonify({"post_id": post_id, "type": type(post_id).__name__})  # int


@app.get("/articles/<slug>")                   # то же, что <string:slug>
def article_by_slug(slug):
    return jsonify({"slug": slug})


@app.get("/files/<path:relpath>")              # слэши разрешены
def read_file(relpath):
    return jsonify({"relpath": relpath})


@app.get("/theme/<any(light, dark):mode>")     # только перечисленные значения
def set_theme(mode):
    return jsonify({"mode": mode})


@app.get("/orders/<uuid:order_id>")
def order_by_uuid(order_id):
    return jsonify({"order_id": str(order_id)})


app.run(debug=True)

from flask import Flask, jsonify, url_for

app = Flask(__name__)

POSTS = {7: {"id": 7, "title": "Как я написал первый API"}}


@app.get("/")
def index():
    return jsonify({
        "posts_url": url_for("post_list"),
        "first_post": url_for("post_detail", post_id=7),
        "absolute": url_for("post_detail", post_id=7, _external=True),
    })


@app.get("/posts")
def post_list():
    return jsonify([
        {**post, "url": url_for("post_detail", post_id=post["id"])}
        for post in POSTS.values()
    ])


@app.get("/posts/<int:post_id>")
def post_detail(post_id):
    post = POSTS.get(post_id)
    if post is None:
        return jsonify({"error": "пост не найден"}), 404
    return jsonify(post)


app.run(debug=True)

from flask import Flask, abort, jsonify, request

app = Flask(__name__)

POSTS = {1: {"id": 1, "title": "Первый пост"}}


@app.errorhandler(404)
def not_found(error):
    return jsonify({
        "error": "ресурс не найден",
        "path": request.path,
    }), 404


@app.errorhandler(405)
def wrong_method(error):
    return jsonify({"error": "метод не поддерживается", "allowed": error.valid_methods}), 405


@app.get("/posts/<int:post_id>")
def post_detail(post_id):
    post = POSTS.get(post_id)
    if post is None:
        abort(404)          # управление уходит в not_found, return не нужен
    return jsonify(post)


app.run(debug=True)
